To execute the `sudo_exec` tool and confirm it's available, you can use the following Python script:

```python
import requests

def execute_sudo_exec(command):
    """Execute a command using sudo_exec"""
    try:
        # Send a POST request to the MCP server with the command
        response = requests.post('http://mcp-server:port/sudo_exec', json=command)

        # Check if the response was successful
        if response.status_code == 200:
            return True
        else:
            print(f"Failed to execute command. Status code: {response.status_code}")
            return False
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {e}")
        return False

def main():
    # Define the command to execute
    command = {"command": "whoami"}

    # Execute the command and get the result
    result = execute_sudo_exec(command)

    if result:
        print("Command executed successfully. Output:")
        output = requests.get(f'http://mcp-server:port/sudo_exec/output/{command["command"]}')
        if output.status_code == 200:
            print(output.json())
        else:
            print("Failed to get output.")

if __name__ == "__main__":
    main()
```

This script sends a POST request to the `sudo_exec` tool with the specified command, and checks if the response was successful. If it was, it retrieves the output of the command using another GET request.

Please replace 'http://mcp-server:port' with the actual URL of your MCP server.

